     1→"use client";
     2→
     3→import React, { useState, useMemo } from "react";
     4→import { useTranslations } from "next-intl";
     5→import { motion, AnimatePresence } from "framer-motion";
     6→import { Music, ArrowRight, Disc, Star } from "lucide-react";
     7→import { NeoNavbar } from "../NeoNavbar";
     8→import { NeoFooter } from "../NeoFooter";
     9→import { NeoHeroSection } from "../ui/NeoHeroSection";
    10→import { NeoCard } from "../ui/NeoCard";
    11→import { BrutalistButton } from "../ui/BrutalistButton";
    12→import { NeoTag } from "../ui/NeoTag";
    13→import { GridBackground } from "../ui/GridBackground";
    14→import { Link } from "@/i18n/routing";
    15→
    16→interface Album {
    17→  id: string;
    18→  title: string;
    19→  img: string | null;
    20→  style: string | null;
    21→  date: string;
    22→  listenLink: string | null;
    23→  collabName?: string | null;
    24→  order?: number;
    25→}
    26→
    27→interface NeoAlbumsPageProps {
    28→  albums: Album[];
    29→}
    30→
    31→const normalizeGenre = (style: string | null) => {
    32→  if (!style) return null;
    33→
    34→  const normalized = style
    35→    .toLowerCase()
    36→    .normalize("NFD")
    37→    .replace(/[\u0300-\u036f]/g, "");
    38→
    39→  if (normalized.includes("metal") || normalized.includes("hardcore")) return "Metal";
    40→  if (
    41→    normalized.includes("hip-hop") ||
    42→    normalized.includes("hip hop") ||
    43→    normalized.includes("rnb") ||
    44→    normalized.includes("trap")
    45→  )
    46→    return "Hip-Hop";
    47→  if (normalized.includes("ambient")) return "Ambient";
    48→  if (normalized.includes("synthwave")) return "Synthwave";
    49→  if (normalized.includes("cyberpunk")) return "Cyberpunk";
    50→  if (normalized.includes("bass")) return "Bass Music";
    51→  if (normalized.includes("pop punk") || normalized.includes("punk")) return "Pop Punk";
    52→  if (normalized.includes("all music genres")) return "Various";
    53→
    54→  return style;
    55→};
    56→
    57→const sortGenres = (genres: string[]) => {
    58→  const order = [
    59→    "Metal",
    60→    "Hip-Hop",
    61→    "Ambient",
    62→    "Bass Music",
    63→    "Synthwave",
    64→    "Cyberpunk",
    65→    "Pop Punk",
    66→    "Various",
    67→  ];
    68→
    69→  const orderIndex = (genre: string) => {
    70→    const index = order.indexOf(genre);
    71→    return index === -1 ? Number.POSITIVE_INFINITY : index;
    72→  };
    73→
    74→  return [...genres].sort((a, b) => {
    75→    const byOrder = orderIndex(a) - orderIndex(b);
    76→    if (byOrder !== 0) return byOrder;
    77→    return a.localeCompare(b);
    78→  });
    79→};
    80→
    81→const staggerContainer = {
    82→  hidden: { opacity: 0 },
    83→  visible: {
    84→    opacity: 1,
    85→    transition: { staggerChildren: 0.08, delayChildren: 0.1 },
    86→  },
    87→};
    88→
    89→const fadeInUp = {
    90→  hidden: { opacity: 0, y: 30, scale: 0.95 },
    91→  visible: { opacity: 1, y: 0, scale: 1, transition: { duration: 0.4 } },
    92→  exit: { opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.3 } },
    93→};
    94→
    95→export const NeoAlbumsPage: React.FC<NeoAlbumsPageProps> = ({ albums }) => {
    96→  const t = useTranslations("albums");
    97→  const [selectedGenre, setSelectedGenre] = useState<string | null>(null);
    98→
    99→  const genreCounts = useMemo(() => {
   100→    const counts = new Map<string, number>();
   101→    for (const album of albums) {
   102→      const genre = normalizeGenre(album.style);
   103→      if (!genre) continue;
   104→      counts.set(genre, (counts.get(genre) ?? 0) + 1);
   105→    }
   106→    return counts;
   107→  }, [albums]);
   108→
   109→  // Extract unique genres
   110→  const genres = useMemo(() => {
   111→    return sortGenres(Array.from(genreCounts.keys()));
   112→  }, [genreCounts]);
   113→
   114→  // Filter albums by genre
   115→  const filteredAlbums = useMemo(() => {
   116→    return albums.filter((album) => {
   117→      const albumGenre = normalizeGenre(album.style);
   118→
   119→      const matchesGenre = !selectedGenre || albumGenre === selectedGenre;
   120→      if (!matchesGenre) return false;
   121→      return true;
   122→    });
   123→  }, [albums, selectedGenre]);
   124→
   125→  // Stats - valeurs fixes demandées par Loïc
   126→  const stats = useMemo(
   127→    () => ({
   128→      total: 20,
   129→      genres: "∞",
   130→      collaborations: albums.filter((a) => a.collabName).length,
   131→      years: "2018 - 2026",
   132→    }),
   133→    [albums]
   134→  );
   135→
   136→  return (
   137→    <div className="min-h-screen bg-neo-bg text-neo-text font-sans selection:bg-neo-text selection:text-neo-accent overflow-x-hidden">
   138→      <GridBackground withAccentGlow />
   139→      <NeoNavbar />
   140→
   141→      <main className="relative z-10 pt-16 md:pt-20">
   142→        {/* Hero */}
   143→        <NeoHeroSection
   144→          badgeNumber="04"
   145→          badge={t("hero.badge")}
   146→          title={t("hero.title")}
   147→          description={t("hero.description")}
   148→          fullViewport
   149→        >
   150→          <div className="flex flex-wrap gap-4">
   151→            <BrutalistButton
   152→              variant="primary"
   153→              size="lg"
   154→              icon={<Music className="w-5 h-5" />}
   155→              onClick={() =>
   156→                document.getElementById("albums-grid")?.scrollIntoView({ behavior: "smooth" })
   157→              }
   158→            >
   159→              {t("hero.cta")}
   160→            </BrutalistButton>
   161→            <Link href="/contact">
   162→              <BrutalistButton variant="secondary" size="lg">
   163→                {t("hero.ctaSecondary")}
   164→              </BrutalistButton>
   165→            </Link>
   166→          </div>
   167→        </NeoHeroSection>
   168→
   169→        {/* Stats Bar */}
   170→        <section className="border-y-4 border-neo-border bg-neo-text text-neo-text-inverse py-12">
   171→          <div className="container mx-auto px-4 md:px-6">
   172→            <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
   173→              {[
   174→                { val: stats.total.toString(), label: t("stats.total") },
   175→                { val: stats.genres.toString(), label: t("stats.genres") },
   176→                { val: stats.collaborations.toString(), label: t("stats.collaborations") },
   177→                { val: stats.years, label: t("stats.period") },
   178→              ].map((stat, i) => (
   179→                <div key={i} className="flex flex-col items-center">
   180→                  <span className="text-4xl md:text-5xl font-black text-neo-accent tracking-tighter">
   181→                    {stat.val}
   182→                  </span>
   183→                  <span className="font-mono text-xs uppercase tracking-widest mt-2 opacity-60">
   184→                    {stat.label}
   185→                  </span>
   186→                </div>
   187→              ))}
   188→            </div>
   189→          </div>
   190→        </section>
   191→
   192→        {/* Filters */}
   193→        <section className="py-8 border-b-2 border-neo-border sticky top-[72px] bg-neo-bg z-30">
   194→          <div className="container mx-auto px-4 md:px-6">
   195→            <div className="flex flex-wrap gap-2">
   196→              <button
   197→                onClick={() => setSelectedGenre(null)}
   198→                className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   199→                  !selectedGenre
   200→                    ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   201→                    : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   202→                }`}
   203→              >
   204→                {t("filterAll")} ({albums.length})
   205→              </button>
   206→              {genres.map((genre) => (
   207→                <button
   208→                  key={genre}
   209→                  onClick={() => setSelectedGenre(genre)}
   210→                  className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   211→                    selectedGenre === genre
   212→                      ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   213→                      : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   214→                  }`}
   215→                >
   216→                  {genre} ({genreCounts.get(genre) ?? 0})
   217→                </button>
   218→              ))}
   219→            </div>
   220→          </div>
   221→        </section>
   222→
   223→        {/* Albums Grid */}
   224→        <section id="albums-grid" className="py-16">
   225→          <div className="container mx-auto px-4 md:px-6">
   226→            <AnimatePresence mode="wait">
   227→              <motion.div
   228→                key={selectedGenre || "all"}
   229→                initial="hidden"
   230→                animate="visible"
   231→                exit="exit"
   232→                variants={staggerContainer}
   233→                className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-16"
   234→              >
   235→                {filteredAlbums.length > 0 ? (
   236→                  filteredAlbums.map((album) => (
   237→                    <motion.div
   238→                      key={album.id}
   239→                      variants={fadeInUp}
   240→                      layout
   241→                      className="group relative"
   242→                    >
   243→                      <Link
   244→                        href={{ pathname: "/albums/[id]", params: { id: album.id } }}
   245→                        className="block"
   246→                      >
   247→                        {/* Cover */}
   248→                        <div className="aspect-square border-4 border-neo-border bg-neo-bg-alt relative mb-6 overflow-hidden shadow-[8px_8px_0px_0px_var(--neo-accent)] group-hover:shadow-[12px_12px_0px_0px_var(--neo-accent)] transition-all duration-300">
   249→                          <div
   250→                            className="w-full h-full bg-cover bg-center group-hover:scale-105 transition-transform duration-500"
   251→                            style={{ backgroundImage: album.img ? `url(${album.img})` : undefined }}
   252→                          />
   253→                          {!album.img && (
   254→                            <div className="absolute inset-0 flex items-center justify-center">
   255→                              <Disc className="w-20 h-20 opacity-20" />
   256→                            </div>
   257→                          )}
   258→                          {/* Overlay with arrow icon */}
   259→                          <div className="absolute inset-0 flex items-center justify-center bg-neo-text/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
   260→                            <div className="w-20 h-20 bg-neo-accent rounded-full flex items-center justify-center border-4 border-neo-border">
   261→                              <ArrowRight size={32} className="text-neo-text-inverse" />
   262→                            </div>
   263→                          </div>
   264→                          {/* Badge Favori pour les albums épinglés */}
   265→                          {album.order !== undefined && album.order < 100 && (
   266→                            <div className="absolute top-3 right-3 bg-neo-accent text-neo-text-inverse px-3 py-1 border-2 border-neo-border flex items-center gap-1.5 font-mono text-xs font-bold uppercase shadow-[3px_3px_0px_0px_var(--neo-border)]">
   267→                              <Star size={12} className="fill-current" />
   268→                              {t("featured")}
   269→                            </div>
   270→                          )}
   271→                        </div>
   272→
   273→                        {/* Info */}
   274→                        <div className="flex items-start justify-between gap-4">
   275→                          <div className="min-w-0">
   276→                            <h3 className="text-2xl font-black uppercase leading-tight mb-2 truncate text-neo-text">
   277→                              {album.title}
   278→                            </h3>
   279→                            <NeoTag variant="accent" size="sm">
   280→                              {normalizeGenre(album.style) || "Genre"}
   281→                            </NeoTag>
   282→                          </div>
   283→                          <span className="font-mono text-sm font-bold border-2 border-neo-border px-2 py-1 flex-shrink-0">
   284→                            {new Date(album.date).getFullYear()}
   285→                          </span>
   286→                        </div>
   287→                      </Link>
   288→                    </motion.div>
   289→                  ))
   290→                ) : (
   291→                  <motion.div variants={fadeInUp} className="col-span-full text-center py-16">
   292→                    <Disc className="w-16 h-16 mx-auto mb-4 opacity-20" />
   293→                    <p className="font-mono text-lg opacity-60">{t("noAlbums")}</p>
   294→                  </motion.div>
   295→                )}
   296→              </motion.div>
   297→            </AnimatePresence>
   298→          </div>
   299→        </section>
   300→
   301→        {/* CTA */}
   302→        <section className="py-24 bg-neo-text">
   303→          <div className="container mx-auto px-4 md:px-6">
   304→            <NeoCard variant="inverted" hover="none" padding="lg" className="text-center">
   305→              <h2 className="text-3xl md:text-4xl font-black uppercase tracking-tight text-neo-text-inverse mb-4">
   306→                {t("albumsCta.title")}
   307→              </h2>
   308→              <p className="font-mono text-lg text-neo-text-inverse/60 max-w-2xl mx-auto mb-8">
   309→                {t("albumsCta.description")}
   310→              </p>
   311→              <div className="flex flex-wrap justify-center gap-4">
   312→                <Link href="/contact">
   313→                  <BrutalistButton
   314→                    variant="dark"
   315→                    size="lg"
   316→                    icon={<ArrowRight className="w-5 h-5" />}
   317→                  >
   318→                    {t("albumsCta.buttonSecondary")}
   319→                  </BrutalistButton>
   320→                </Link>
   321→              </div>
   322→            </NeoCard>
   323→          </div>
   324→        </section>
   325→      </main>
   326→
   327→      <NeoFooter />
   328→    </div>
   329→  );
   330→};
   331→
   332→export default NeoAlbumsPage;
   333→

